"""Guards against pipelines whose exit status is silently discarded.

The default `run:` shell on Linux runners is `bash -e {0}`, which does not
enable `pipefail`. A step that pipes a test command into `tee` therefore exits
with tee's status, so a failing test run is recorded as a pass and published as
a normalized success. Declaring `shell: bash` selects
`bash --noprofile --norc -eo pipefail {0}` instead.
"""

from pathlib import Path
import re
import unittest

ROOT = Path(__file__).resolve().parents[3]
WORKFLOWS = ROOT / '.github/workflows'

# Generated by GitHub Agentic Workflows from ai-analyzer.md; not hand-edited.
EXCLUDED = {'ai-analyzer.lock.yml'}

def _split_steps(workflow_text):
    """Splits a workflow into step blocks keyed on the `- ` list marker."""
    steps = []
    current = None
    for line in workflow_text.splitlines():
        if re.match(r'^\s*- (?:name|uses|id|run|shell|with):', line):
            if current is not None:
                steps.append('\n'.join(current))
            current = [line]
        elif current is not None:
            current.append(line)
    if current is not None:
        steps.append('\n'.join(current))
    return steps


def piped_steps_without_pipefail(workflow_text):
    """Returns the name of each step that pipes a command without pipefail."""
    offenders = []
    for step in _split_steps(workflow_text):
        if '| tee ' not in step:
            continue
        if re.search(r'^\s*shell:\s*bash\s*$', step, flags=re.M):
            continue
        if 'PIPESTATUS' in step:
            continue
        name = re.search(r'- name:\s*(.+)', step)
        offenders.append(name.group(1).strip() if name else step[:60])
    return offenders


class WorkflowPipefailTest(unittest.TestCase):

    def test_piped_run_steps_declare_pipefail(self):
        offenders = {}
        for workflow in sorted(WORKFLOWS.glob('*.y*ml')):
            if workflow.name in EXCLUDED:
                continue
            found = piped_steps_without_pipefail(
                workflow.read_text(encoding='utf-8'))
            if found:
                offenders[workflow.name] = found

        self.assertEqual(
            offenders, {},
            'These steps pipe through tee without pipefail, so a failing '
            'command is reported as a pass. Add `shell: bash` to the step.')

    def test_detects_a_step_missing_pipefail(self):
        # The guard must fail on the shape it exists to catch.
        offenders = piped_steps_without_pipefail(
            '      - name: Run tests\n'
            '        run: |\n'
            '          go test ./... | tee "$RUNNER_TEMP/go-test.json"\n')

        self.assertEqual(offenders, ['Run tests'])

    def test_accepts_a_step_declaring_bash(self):
        offenders = piped_steps_without_pipefail(
            '      - name: Run tests\n'
            '        shell: bash\n'
            '        run: |\n'
            '          go test ./... | tee "$RUNNER_TEMP/go-test.json"\n')

        self.assertEqual(offenders, [])


if __name__ == '__main__':
    unittest.main()
